<?php
namespace App\Services;use App\Models\Device;use App\Models\TelemetryRecord;use Illuminate\Validation\ValidationException;
final class TelemetrySchemaService{public function record(Device $device,string $key,mixed $value):TelemetryRecord{$definition=$device->parameters()->where('key',$key)->first();if(!$definition){if($device->device_template_id||!is_numeric($value))throw ValidationException::withMessages([$key=>['Unknown parameter key for this Device schema.']]);return TelemetryRecord::create(['device_id'=>$device->id,'key'=>$key,'value'=>$value,'typed_value'=>(float)$value,'recorded_at'=>now()]);}$c=$definition->configuration??[];$valid=match($definition->data_type){'string'=>is_string($value)&&mb_strlen($value)<=($c['maxLength']??10000),'integer'=>is_int($value)&&$this->range($value,$c),'number'=>(is_int($value)||is_float($value))&&is_finite((float)$value)&&$this->range((float)$value,$c),'boolean'=>is_bool($value),'enum'=>is_string($value)&&in_array($value,$c['options']??[],true),default=>false};if(!$valid)throw ValidationException::withMessages([$key=>["Value does not satisfy the {$definition->data_type} parameter contract."]]);$numeric=match($definition->data_type){'integer','number'=>$value,'boolean'=>$value?1:0,default=>0};return TelemetryRecord::create(['device_id'=>$device->id,'key'=>$key,'value'=>$numeric,'typed_value'=>$value,'unit'=>$definition->unit,'recorded_at'=>now()]);}private function range(float|int$value,array$c):bool{return(!isset($c['min'])||$value>=$c['min'])&&(!isset($c['max'])||$value<=$c['max']);}}
